// Fan the requisition's account ids out to one item each, so the three
// per-account GETs below run once per account.
//
// 'Fetch requisition' has alwaysOutputData on. A requisition whose
// consent has expired returns an empty `accounts` array rather than an
// error, and without the guard below the branch would die here and
// Jytte would keep showing the last balance forever with no banner.
// Emitting a marker item instead lets Normalize report it honestly.

const req = $input.first().json || {};
const ids = Array.isArray(req.accounts) ? req.accounts : [];

if (ids.length === 0) {
  return [{ json: { account_id: null, consent_status: req.status || 'unknown' } }];
}

return ids.map((id) => ({ json: { account_id: id, consent_status: req.status || 'LN' } }));

// Normalize GoCardless Bank Account Data into the Jytte `bank` payload.
//
// Input : three parallel per-account node outputs, each one item per
//         account in the SAME order, because every one of them ran once
//         per item coming out of 'Split accounts'. That is why they are
//         zipped by index below rather than joined on a key - there is
//         no shared key in the responses to join on.
// Output: exactly one item, the body POSTed to /widgets/bank/state.

const cfg = $('Config').first().json;
const lookbackDays = Number(cfg.lookback_days) || 30;

const details = $('Fetch details').all();
const balances = $('Fetch balances').all();
const txPages = $('Fetch transactions').all();

// MONEY RULE (project rule 1): integer minor units, never float.
// parseFloat('123.45') * 100 is 12344.999999999998, so the round is not
// cosmetic - without it every other amount lands a oere low.
const toOere = (s) => {
  const n = parseFloat(String(s == null ? '0' : s).replace(',', '.'));
  return isNaN(n) ? 0 : Math.round(n * 100);
};

// Hand-rolled rather than toLocaleString: an n8n image built with
// small-icu silently falls back to en-US and every amount would render
// with the separators swapped.
const kr = (oere) => {
  const neg = oere < 0;
  const whole = String(Math.floor(Math.abs(oere) / 100));
  const cents = String(Math.abs(oere) % 100).padStart(2, '0');
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (neg ? '-' : '') + grouped + ',' + cents;
};

const pickBalance = (payload) => {
  // Preference order matters: interimAvailable is what the bank app
  // shows you, closingBooked is yesterday's end-of-day. Showing the
  // second as if it were the first is how a budget page ends up
  // disagreeing with the phone.
  const list = (payload && payload.balances) || [];
  const order = ['interimAvailable', 'expected', 'closingBooked', 'forwardAvailable'];
  for (const want of order) {
    const hit = list.find((b) => b.balanceType === want);
    if (hit) return hit;
  }
  return list[0] || null;
};

const today = new Date();
const cutoff = new Date(today.getTime() - lookbackDays * 86400000)
  .toISOString()
  .slice(0, 10);

const accounts = [];
const transactions = [];
let oldestBalanceDate = null;

for (let i = 0; i < details.length; i++) {
  const d = (details[i] && details[i].json && details[i].json.account) || {};
  const bal = pickBalance(balances[i] && balances[i].json);
  const acctId =
    $('Split accounts').all()[i] &&
    $('Split accounts').all()[i].json.account_id;

  if (!acctId) continue;

  const iban = String(d.iban || '');
  const balOere = bal ? toOere(bal.balanceAmount && bal.balanceAmount.amount) : 0;
  const refDate = (bal && (bal.referenceDate || bal.lastChangeDateTime)) || null;
  if (refDate && (!oldestBalanceDate || refDate < oldestBalanceDate)) {
    oldestBalanceDate = String(refDate).slice(0, 10);
  }

  accounts.push({
    id: acctId,
    // name is what the owner called the account; product is the bank's
    // own label. Either beats printing a UUID at the user.
    name: d.name || d.product || d.details || 'Konto',
    bank: d.ownerName || '',
    // LAST FOUR ONLY. A full IBAN in a cached widget payload is an
    // account number sitting in a database that renders HTML. Same
    // reasoning as calendar.json sending attendee names, not addresses.
    iban_tail: iban ? iban.slice(-4) : '',
    currency: (bal && bal.balanceAmount && bal.balanceAmount.currency) || d.currency || 'DKK',
    balance_oere: balOere,
    balance_kr: kr(balOere),
    balance_at: refDate ? String(refDate).slice(0, 10) : null,
    balance_type: (bal && bal.balanceType) || null,
  });

  const page = (txPages[i] && txPages[i].json && txPages[i].json.transactions) || {};
  const booked = Array.isArray(page.booked) ? page.booked : [];
  const pending = Array.isArray(page.pending) ? page.pending : [];

  for (const t of booked.concat(pending)) {
    const date = String(t.bookingDate || t.valueDate || '').slice(0, 10);
    if (date && date < cutoff) continue;
    const amtOere = toOere(t.transactionAmount && t.transactionAmount.amount);
    transactions.push({
      id: t.transactionId || t.internalTransactionId || `${acctId}-${date}-${amtOere}`,
      account_id: acctId,
      date: date || null,
      text:
        t.remittanceInformationUnstructured ||
        (Array.isArray(t.remittanceInformationUnstructuredArray)
          ? t.remittanceInformationUnstructuredArray.join(' ')
          : '') ||
        t.additionalInformation ||
        '',
      counterparty: t.creditorName || t.debtorName || '',
      amount_oere: amtOere,
      amount_kr: kr(amtOere),
      currency: (t.transactionAmount && t.transactionAmount.currency) || 'DKK',
      kind: amtOere < 0 ? 'out' : 'in',
      pending: pending.indexOf(t) !== -1,
    });
  }
}

transactions.sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));

const sum = (f) => transactions.filter(f).reduce((n, t) => n + t.amount_oere, 0);
const balanceTotal = accounts.reduce((n, a) => n + a.balance_oere, 0);
const inOere = sum((t) => t.amount_oere > 0);
const outOere = sum((t) => t.amount_oere < 0);

// Consent runs out after 90 days and the BANK starts refusing, not n8n.
// The workflow stays green, the numbers quietly stop moving. Age of the
// newest balance is the only signal that catches that.
let staleDays = 0;
if (oldestBalanceDate) {
  staleDays = Math.max(
    0,
    Math.round((Date.parse(today.toISOString().slice(0, 10)) - Date.parse(oldestBalanceDate)) / 86400000)
  );
}

const consent = $('Split accounts').first().json.consent_status;
const ready = accounts.length > 0;

return [
  {
    json: {
      ready: ready,
      source: 'n8n',
      provider: 'gocardless-bank-account-data',
      reason: ready
        ? null
        : `samtykket giver ingen konti (status ${consent}) - gennemfoer bank-linket igen`,
      fetched_at: new Date().toISOString(),
      lookback_days: lookbackDays,
      consent_status: consent,
      stale_days: staleDays,
      totals: {
        accounts: accounts.length,
        balance_oere: balanceTotal,
        balance_kr: kr(balanceTotal),
        in_30d_oere: inOere,
        in_30d_kr: kr(inOere),
        out_30d_oere: outOere,
        out_30d_kr: kr(outOere),
      },
      accounts: accounts,
      transactions: transactions,
      summary:
        'bank: ' + kr(balanceTotal) + ' kr paa ' + accounts.length + ' konti',
    },
  },
];
